let alias=save.get('iron.alias',save.get('rift.name',save.get('apex.pilot'))),state='menu',selected=0,levelIndex=0,unlocked=0,world,player,camera=0,score=0,lives=5,checkpoint=80,clock=0,keys={},shots=[],hostile=[],bombs=[],particles=[],pickups=[],shake=0,flash=0,noticeTime=0,deathTime=0,bossActive=false,previousState='play',frameTime=0,accumulator=0,stepSound=0;
const controls={arrowleft:'a',arrowright:'d',arrowup:'w',arrowdown:'s',z:'j',x:'k',c:'l',' ':'k'};
function profileKey(k){return 'iron.'+k+'.'+alias.toLocaleLowerCase()}
function readProgress(){unlocked=clamp(parseInt(save.get(profileKey('unlocked'),'0'),10)||0,0,7);selected=unlocked}
function playerBody(){return {x:player.x-11,y:player.y-(player.crouch?23:42),w:22,h:player.crouch?23:42}}
function overlaps(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y}
function burst(x,y,color,n=16,force=150){for(let i=0;i<n;i++)particles.push({x,y,vx:random(-force,force),vy:random(-force,force),life:random(.2,.7),color,size:random(2,5)})}
function notify(message,duration=2){$('notice').textContent=message;noticeTime=duration}
// All stage geometry, characters, names and compositions are original.
function buildLevel(index){const d=levels[index],ground=[],platforms=[],enemies=[],items=[],checks=[80,1450,2850,4250].filter(x=>x<d.width-1000);const gaps=[1080,2480,3880].filter(x=>x<d.width-1000).map(x=>({x,w:100+(index%3)*12}));let edge=0;for(const g of gaps){ground.push({x:edge,y:450,w:g.x-edge,h:120});edge=g.x+g.w}ground.push({x:edge,y:450,w:d.width-edge,h:120});
for(let i=0;i<Math.floor((d.width-1000)/680);i++){const base=i*680;platforms.push({x:base+280,y:355-(index%2)*12,w:140,h:15},{x:base+480,y:285+(index%3)*10,w:110,h:15});enemies.push(makeEnemy(base+430,450,i%3===1?'turret':'soldier',index),makeEnemy(base+530,platforms.at(-1).y,'turret',index));if(i>0||index>0)enemies.push(makeEnemy(base+680,255,'drone',index));if(i%2===0)items.push({x:base+345,y:platforms.at(-2).y-25,type:i===0?'spread':i===2?'beam':'health',used:false});}
const boss={x:d.width-180,y:450,w:105,h:105,hp:65+index*9,max:65+index*9,cool:2,phase:0,t:0,flash:0,charge:0,beam:0};
return {ground,platforms,enemies,items,checks,boss,gaps,width:d.width,index};}
function makeEnemy(x,y,type,index){return {x,y,baseY:y,home:x,type,hp:type==='turret'?4:type==='drone'?2:2,cool:1+(x%7)*.15,active:false,dead:false,t:0,flash:0,speed:30+index*3}}
function newPlayer(){return {x:checkpoint,y:420,vy:0,vx:0,ground:false,crouch:false,face:1,hp:3,inv:2.3,cool:0,weapon:'rifle',ammo:0,grenades:3,grenadeCool:0,jumpBuffer:0,coyote:0,walk:0}}
function loadLevel(index,fresh=true){levelIndex=clamp(index,0,7);world=buildLevel(levelIndex);checkpoint=80;player=newPlayer();camera=0;shots=[];hostile=[];bombs=[];particles=[];pickups=[];bossActive=false;shake=0;flash=0;keys={};if(fresh){lives=5;score=0}state='play';$('menu').hidden=true;$('overlay').hidden=true;$('manual').hidden=true;$('hud').hidden=false;$('keybar').hidden=false;$('touch').hidden=false;$('pause').hidden=false;$('logout').hidden=true;$('boss-hud').hidden=true;document.body.classList.add('playing');$('sector').textContent='SECTOR '+String(levelIndex+1).padStart(2,'0')+' / '+levels[levelIndex].place;$('hud-name').textContent=levels[levelIndex].name.toUpperCase();$('music-title').textContent='♪ '+levels[levelIndex].track.toUpperCase();notify('MISIÓN '+String(levelIndex+1).padStart(2,'0')+' / '+levels[levelIndex].name.toUpperCase(),2.5);startMusic(levelIndex);sfx('start');updateHUD()}
function renderMission(){const d=levels[selected];$('mission-title').textContent=String(selected+1).padStart(2,'0')+' / '+d.name;$('mission-description').textContent=d.brief;$('mission-boss').textContent='JEFE / '+d.boss;$('mission-record').textContent='RÉCORD '+save.get(profileKey('best'),'0');$('mission-status').textContent=save.get(profileKey('complete'))==='1'?'Operación completada. Puedes repetir cualquier misión.':(unlocked+1)+' de 8 sectores disponibles · 5 vidas por misión';$('missions').innerHTML='';levels.forEach((l,i)=>{const b=document.createElement('button');b.textContent=String(i+1).padStart(2,'0');b.disabled=i>unlocked;b.title=l.name+(i>unlocked?' · Bloqueada':'');b.setAttribute('aria-label','Misión '+(i+1)+': '+l.name);b.setAttribute('aria-pressed',String(i===selected));b.onclick=()=>{selected=i;renderMission();world=buildLevel(i);levelIndex=i;camera=350};$('missions').appendChild(b)})}
function menu(){state='menu';keys={};stopMusic();$('menu').hidden=false;$('overlay').hidden=true;$('manual').hidden=true;$('hud').hidden=true;$('keybar').hidden=true;$('touch').hidden=true;$('pause').hidden=true;$('boss-hud').hidden=true;$('notice').textContent='';$('logout').hidden=!alias;$('login-panel').hidden=!!alias;$('ready-panel').hidden=!alias;document.body.classList.remove('playing');$('operator').textContent=alias.toUpperCase();readProgress();renderMission();levelIndex=selected;world=buildLevel(selected);checkpoint=80;player=newPlayer();player.x=620;player.y=450;camera=240;particles=[];hostile=[];shots=[];bombs=[];bossActive=false}
$('login').onsubmit=event=>{event.preventDefault();const v=$('alias').value.trim();if(v.length<2){$('alias').setCustomValidity('Escribe al menos 2 caracteres.');$('alias').reportValidity();return}alias=v;save.set('iron.alias',v);menu()};$('alias').oninput=()=> $('alias').setCustomValidity('');$('logout').onclick=()=>{alias='';save.set('iron.alias','');menu()};$('deploy').onclick=()=>loadLevel(selected);$('return').onclick=menu;
function dialog(label,title,copy,button){$('overlay').hidden=false;$('dialog-label').textContent=label;$('dialog-title').textContent=title;$('dialog-copy').textContent=copy;$('continue').textContent=button}
function pause(){if(state==='paused'){state=previousState;$('overlay').hidden=true;startMusic(levelIndex);return}if(!['play','dying'].includes(state))return;previousState=state;state='paused';keys={};stopMusic();dialog('OPERACIÓN EN PAUSA','Mantén la posición.','La misión continuará exactamente desde aquí.','CONTINUAR →')}
$('pause').onclick=pause;$('continue').onclick=()=>{if(state==='paused')pause();else if(state==='clear')loadLevel(levelIndex+1,false);else if(state==='over')loadLevel(levelIndex,true);else if(state==='victory')menu()};$('help').onclick=()=>{$('manual').hidden=false};$('close-help').onclick=()=>{$('manual').hidden=true};$('full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{$('full').title='Usa F11 para pantalla completa'}};
function keyDown(k){keys[k]=true;if(k==='p'||k==='escape'){pause();return}if(state!=='play')return;if(k==='k')player.jumpBuffer=.16;if(k==='l')grenade()}
window.addEventListener('keydown',ev=>{if(ev.target.matches('input'))return;const raw=ev.key.toLowerCase(),k=controls[raw]||raw;if(['a','d','w','s','j','k','l','p','escape'].includes(k)){ev.preventDefault();if(!ev.repeat)keyDown(k)}});window.addEventListener('keyup',ev=>{const raw=ev.key.toLowerCase();keys[controls[raw]||raw]=false});
for(const b of document.querySelectorAll('[data-key]')){b.onpointerdown=ev=>{ev.preventDefault();b.setPointerCapture(ev.pointerId);keyDown(b.dataset.key)};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>{keys[b.dataset.key]=false}}
window.addEventListener('blur',()=>{keys={};if(['play','dying'].includes(state))pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){stopMusic();keys={};if(['play','dying'].includes(state))pause()}});
// Original Web Audio score: eight distinct motifs and tempos, with bass and percussion.
let audio=null,muted=true,musicBus=null,musicTimer=null,musicNext=0,musicStep=0;
function tone(freq,when,duration,type='square',gain=.07,bus=null,endFreq=null){if(!audio||muted)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,when);if(endFreq)o.frequency.exponentialRampToValueAtTime(Math.max(15,endFreq),when+duration);g.gain.setValueAtTime(.001,when);g.gain.linearRampToValueAtTime(gain,when+.006);g.gain.exponentialRampToValueAtTime(.001,when+duration);o.connect(g);g.connect(bus||audio.destination);o.start(when);o.stop(when+duration+.01);o.onended=()=>{o.disconnect();g.disconnect()}}
function noise(when,duration,gain=.08,bus=null){if(!audio||muted)return;const count=Math.floor(audio.sampleRate*duration),buffer=audio.createBuffer(1,count,audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<count;i++)data[i]=(Math.random()*2-1)*(1-i/count);const source=audio.createBufferSource(),g=audio.createGain(),filter=audio.createBiquadFilter();source.buffer=buffer;filter.type='lowpass';filter.frequency.value=3000;g.gain.value=gain;source.connect(filter);filter.connect(g);g.connect(bus||audio.destination);source.start(when);source.onended=()=>{source.disconnect();filter.disconnect();g.disconnect()}}
function sfx(kind){if(!audio||muted)return;const t=audio.currentTime;switch(kind){case'shot':tone(720,t,.065,'square',.035,null,130);noise(t,.035,.018);break;case'beam':tone(1250,t,.12,'sawtooth',.035,null,200);break;case'jump':tone(180,t,.16,'square',.04,null,650);break;case'land':noise(t,.05,.04);break;case'step':noise(t,.025,.012);break;case'hit':noise(t,.13,.12);tone(90,t,.2,'triangle',.12,null,25);break;case'explode':noise(t,.4,.16);tone(90,t,.3,'sine',.17,null,18);break;case'death':[380,270,190,95].forEach((f,i)=>tone(f,t+i*.1,.18,'sawtooth',.065,null,f*.5));noise(t,.3,.1);break;case'pickup':[440,660,880].forEach((f,i)=>tone(f,t+i*.07,.12,'square',.05));break;case'checkpoint':[330,440,660].forEach((f,i)=>tone(f,t+i*.1,.18,'triangle',.07));break;case'clear':[330,415,494,660,830].forEach((f,i)=>tone(f,t+i*.1,.3,'square',.045));break;case'boss':tone(80,t,.8,'sawtooth',.08,null,160);break;case'grenade':tone(220,t,.1,'triangle',.07,null,90);break;case'start':tone(520,t,.2,'square',.04,null,260);break}}
function stopMusic(){if(musicTimer)clearInterval(musicTimer);musicTimer=null;if(musicBus){const old=musicBus;old.gain.setTargetAtTime(0,audio.currentTime,.025);setTimeout(()=>old.disconnect(),200);musicBus=null}}
function startMusic(index){stopMusic();if(muted||!audio||document.hidden||state==='paused')return;const d=levels[index];musicBus=audio.createGain();musicBus.gain.value=.34;musicBus.connect(audio.destination);musicStep=0;musicNext=audio.currentTime+.03;const schedule=()=>{const beat=60/d.bpm/2;if(musicNext<audio.currentTime-.2)musicNext=audio.currentTime+.01;while(musicNext<audio.currentTime+.15){const n=musicStep%16,hz=n=>440*2**((n-69)/12),m=d.root+d.melody[n]+12;tone(hz(m),musicNext,beat*.65,index%3===0?'square':'triangle',.10,musicBus);if(n%2===0)tone(hz(d.root-12+(n>=8?5:0)),musicNext,beat*1.6,'triangle',.23,musicBus);if(n%4===0)tone(150,musicNext,.12,'sine',.4,musicBus,35);if(n%4===2)noise(musicNext,.07,.10,musicBus);noise(musicNext,.018,.025,musicBus);if(n===0)for(const chord of [0,7,12])tone(hz(d.root+chord),musicNext,beat*6,'triangle',.018,musicBus);musicNext+=beat;musicStep++}};schedule();musicTimer=setInterval(schedule,45)}
$('audio').onclick=async()=>{if(muted){try{audio??=new(window.AudioContext||window.webkitAudioContext)();await audio.resume();muted=false;startMusic(state==='menu'?selected:levelIndex)}catch{$('audio').textContent='AUDIO NO DISPONIBLE';return}}else{muted=true;stopMusic()}$('audio').textContent=muted?'♪ AUDIO OFF':'♪ AUDIO ON'};
function shoot(){if(player.cool>0)return;let dx=keys.d?1:keys.a?-1:player.face,dy=keys.w?-1:keys.s&&!player.ground?1:0;if(dy&&!keys.a&&!keys.d)dx=0;const norm=Math.hypot(dx,dy)||1;dx/=norm;dy/=norm;const y=player.y-(player.crouch?14:29);const spread=player.weapon==='spread'?[-.19,0,.19]:[0];for(const angle of spread){const co=Math.cos(angle),si=Math.sin(angle);shots.push({x:player.x+dx*19,y:y+dy*15,vx:(dx*co-dy*si)*(player.weapon==='beam'?810:660),vy:(dx*si+dy*co)*(player.weapon==='beam'?810:660),life:1.25,damage:player.weapon==='beam'?3:1,beam:player.weapon==='beam'})}player.cool=player.weapon==='beam'?.2:.145;if(player.weapon!=='rifle'){player.ammo--;if(player.ammo<=0)player.weapon='rifle'}sfx(player.weapon==='beam'?'beam':'shot')}
function grenade(){if(player.grenades<=0||player.grenadeCool>0)return;player.grenades--;player.grenadeCool=.5;bombs.push({x:player.x,y:player.y-35,vx:player.face*260,vy:-340,life:1.15});sfx('grenade')}
function hurt(){if(state!=='play'||player.inv>0)return;player.hp--;player.inv=1.5;shake=4;flash=.15;sfx('hit');if(player.hp<=0)die()}
function die(){if(state!=='play')return;lives--;state='dying';deathTime=1.1;keys={};burst(player.x,player.y-25,'#ffad67',35,240);shake=10;sfx('death');if(lives<=0)stopMusic()}
function respawn(){if(lives<=0){state='over';saveBest();dialog('OPERADOR FUERA DE COMBATE','Vuelve a intentarlo.','Puedes reiniciar este sector con 5 vidas. Tus misiones desbloqueadas permanecen guardadas.','REINICIAR SECTOR →');return}player=newPlayer();shots=[];hostile=[];bombs=[];world.enemies.forEach(en=>{if(Math.abs(en.x-checkpoint)<200)en.dead=true});if(bossActive){world.boss.hp=world.boss.max;world.boss.cool=2;world.boss.charge=0;world.boss.beam=0}camera=clamp(player.x-260,0,world.width-960);state='play';notify('REINCORPORACIÓN / '+lives+' VIDAS',1.3)}
function saveBest(){const best=Number(save.get(profileKey('best'),'0'))||0;if(score>best)save.set(profileKey('best'),score)}
function complete(){if(state!=='play')return;score+=2500+levelIndex*500;saveBest();sfx('clear');stopMusic();keys={};$('boss-hud').hidden=true;unlocked=Math.max(unlocked,Math.min(7,levelIndex+1));save.set(profileKey('unlocked'),unlocked);if(levelIndex===7){state='victory';save.set(profileKey('complete'),1);dialog('OPERACIÓN ECLIPSE / COMPLETADA','La señal ha caído.',levels[levelIndex].end+' Puntuación: '+score+'.','VOLVER AL CUARTEL →')}else{state='clear';lives=Math.min(7,lives+1);dialog('SECTOR '+(levelIndex+1)+' / COMPLETADO','Objetivo neutralizado.',levels[levelIndex].end+' Has recuperado una vida.','SIGUIENTE MISIÓN →')}}
function damageEnemy(en,damage){en.hp-=damage;en.flash=.12;burst(en.x,en.y-20,'#ffe293',3,60);if(en.hp<=0&&!en.dead){en.dead=true;score+=en.type==='turret'?180:100;burst(en.x,en.y-20,'#ff994d',18,120);sfx('explode');if(Math.random()<.16)pickups.push({x:en.x,y:en.y-24,type:Math.random()<.5?'health':'spread',used:false})}}
function damageBoss(damage){if(!bossActive||world.boss.hp<=0)return;world.boss.hp=Math.max(0,world.boss.hp-damage);world.boss.flash=.08;if(world.boss.hp<=0){burst(world.boss.x,world.boss.y-65,levels[levelIndex].accent,80,300);shake=14;sfx('explode');complete()}}
function fireAt(x,y,count=1,speed=170,arc=.16){const angle=Math.atan2(player.y-28-y,player.x-x);for(let i=0;i<count;i++){const a=angle+(i-(count-1)/2)*arc;hostile.push({x,y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,r:4,life:7})}}
function enemyBox(en){return en.type==='drone'?{x:en.x-18,y:en.y-16,w:36,h:30}:{x:en.x-14,y:en.y-37,w:28,h:37}}
function bossBox(){const b=world.boss;return {x:b.x-b.w/2,y:b.y-b.h,w:b.w,h:b.h}}
function bossUpdate(dt){const b=world.boss;b.t+=dt;b.cool-=dt;b.flash=Math.max(0,b.flash-dt);b.beam=Math.max(0,b.beam-dt);if(b.charge>0){b.charge-=dt;if(b.charge<=0){b.beam=.5;shake=4;sfx('beam')}}if(b.beam>0&&player.y>415&&player.x<b.x-50)hurt();if(b.cool>0)return;b.phase++;const rage=b.hp<b.max*.45;switch(levelIndex){case 0:fireAt(b.x-50,b.y-65,rage?3:1,190,.2);b.cool=rage?.8:1.05;break;case 1:fireAt(b.x-45,b.y-85,3,170,.28);fireAt(b.x-55,b.y-28,1,200);b.cool=1.55;break;case 2:for(let i=0;i<5;i++)hostile.push({x:b.x-50,y:b.y-60,vx:-170-i*12,vy:-230+i*65,r:6,life:6,gravity:210});b.cool=1.8;break;case 3:for(let i=0;i<4;i++)hostile.push({x:camera+150+i*180+(b.phase%2)*60,y:40,vx:-20,vy:180,r:6,life:4});fireAt(b.x-50,b.y-50,1,220);b.cool=1.6;break;case 4:fireAt(b.x-35,b.y-75,5,145,.25);b.cool=1.65;break;case 5:fireAt(b.x-50,b.y-100,3,190,.3);if(b.phase%3===0)world.enemies.push(makeEnemy(b.x-180,450,'soldier',6));b.cool=1.25;break;case 6:if(b.phase%3===0){b.charge=1.1;notify('BARRIDO BAJO / ¡SALTA!',1.1)}else fireAt(b.x-50,b.y-85,3,185,.22);b.cool=1.75;break;case 7:for(let i=0;i<8;i++){const a=Math.PI*.5+i*Math.PI/7;hostile.push({x:b.x-20,y:b.y-75,vx:Math.cos(a)*175,vy:Math.sin(a)*175,r:5,life:6})}if(rage)fireAt(b.x-50,b.y-45,2,230,.18);b.cool=rage?1.1:1.5;break}}
function update(dt){clock+=dt;shake=Math.max(0,shake-dt*30);flash=Math.max(0,flash-dt);if(noticeTime>0){noticeTime-=dt;if(noticeTime<=0)$('notice').textContent=''}for(const a of particles){a.x+=a.vx*dt;a.y+=a.vy*dt;a.vy+=350*dt;a.life-=dt}particles=particles.filter(a=>a.life>0);if(state==='dying'){deathTime-=dt;if(deathTime<=0)respawn();return}if(state!=='play')return;
player.inv=Math.max(0,player.inv-dt);player.cool=Math.max(0,player.cool-dt);player.grenadeCool=Math.max(0,player.grenadeCool-dt);player.jumpBuffer=Math.max(0,player.jumpBuffer-dt);player.coyote=player.ground?.1:Math.max(0,player.coyote-dt);player.crouch=!!keys.s&&player.ground;const direction=(keys.d?1:0)-(keys.a?1:0);if(direction)player.face=direction;player.vx=player.crouch?0:direction*230;if(player.jumpBuffer>0&&player.coyote>0){player.vy=-550;player.ground=false;player.coyote=0;player.jumpBuffer=0;sfx('jump')}const oldY=player.y;player.x=clamp(player.x+player.vx*dt,bossActive?world.width-925:12,world.width-75);player.vy+=1280*dt;player.y+=player.vy*dt;const wasGround=player.ground;player.ground=false;for(const plat of [...world.ground,...world.platforms]){if(player.x+9>plat.x&&player.x-9<plat.x+plat.w&&oldY<=plat.y+.5&&player.y>=plat.y&&player.vy>=0){player.y=plat.y;player.vy=0;player.ground=true;break}}if(player.ground&&!wasGround)sfx('land');if(player.y>595){die();return}if(direction&&player.ground){player.walk+=dt*16;stepSound-=dt;if(stepSound<=0){sfx('step');stepSound=.19}}if(keys.j)shoot();
for(const x of world.checks){if(player.x>=x&&checkpoint<x){checkpoint=x;notify('PUNTO DE RETORNO',1.4);sfx('checkpoint')}}if(!bossActive&&player.x>world.width-900){bossActive=true;checkpoint=world.width-850;$('boss-hud').hidden=false;$('boss-name').textContent=levels[levelIndex].boss;hostile=[];notify('ALERTA / '+levels[levelIndex].boss,2);sfx('boss')}
camera=clamp(player.x-300,0,world.width-960);if(bossActive)camera=world.width-960;
for(const en of world.enemies){if(en.dead||en.x<camera-130||en.x>camera+1100)continue;en.active=true;en.t+=dt;en.cool-=dt;en.flash=Math.max(0,en.flash-dt);if(en.type==='drone'){en.y=en.baseY+Math.sin(en.t*2.2)*44;en.x=en.home+Math.sin(en.t*.8)*60}else if(en.type==='soldier'){const step=Math.sign(player.x-en.x)*en.speed*dt;const safe=world.ground.some(g=>en.x+step>g.x+12&&en.x+step<g.x+g.w-12);if(safe&&Math.abs(player.x-en.x)>90)en.x+=step}if(en.cool<=0&&Math.abs(player.x-en.x)<730){fireAt(en.x,en.y-(en.type==='drone'?0:27),1,140+levelIndex*10);en.cool=en.type==='turret'?1.7:2.2+Math.random()*.6}if(overlaps(playerBody(),enemyBox(en)))hurt()}
if(bossActive){bossUpdate(dt);if(overlaps(playerBody(),bossBox()))hurt()}
for(const b of shots){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;if(b.life<=0)continue;const box={x:b.x-5,y:b.y-3,w:10,h:6};let hit=false;for(const en of world.enemies){if(!en.dead&&en.active&&overlaps(box,enemyBox(en))){damageEnemy(en,b.damage);hit=true;break}}if(!hit&&bossActive&&overlaps(box,bossBox())){damageBoss(b.damage);hit=true}if(hit)b.life=0}shots=shots.filter(b=>b.life>0&&b.x>camera-70&&b.x<camera+1050&&b.y>-80&&b.y<600);
for(const b of hostile){b.x+=b.vx*dt;b.y+=b.vy*dt;if(b.gravity)b.vy+=b.gravity*dt;b.life-=dt;if(overlaps({x:b.x-b.r,y:b.y-b.r,w:b.r*2,h:b.r*2},playerBody())){hurt();b.life=0}}hostile=hostile.filter(b=>b.life>0&&b.x>camera-100&&b.x<camera+1100&&b.y>-100&&b.y<570);
for(const b of bombs){const prev=b.y;b.vy+=800*dt;b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;for(const g of [...world.ground,...world.platforms])if(b.x>g.x&&b.x<g.x+g.w&&prev<=g.y&&b.y>=g.y&&b.vy>0){b.y=g.y-2;b.vy*=-.35;b.vx*=.6;break}if(b.life<=0){burst(b.x,b.y,'#ffbc64',45,240);sfx('explode');shake=7;for(const en of world.enemies)if(!en.dead&&Math.hypot(en.x-b.x,en.y-20-b.y)<150)damageEnemy(en,8);if(bossActive&&Math.hypot(world.boss.x-b.x,world.boss.y-45-b.y)<170)damageBoss(16)}}bombs=bombs.filter(b=>b.life>0);
for(const item of [...world.items,...pickups])if(!item.used&&overlaps({x:item.x-14,y:item.y-16,w:28,h:32},playerBody())){item.used=true;if(item.type==='health')player.hp=Math.min(3,player.hp+1);else{player.weapon=item.type;player.ammo=180}score+=100;sfx('pickup');notify(item.type==='health'?'RESISTENCIA RECUPERADA':item.type==='spread'?'DISPARO TRIPLE':'BLÁSTER DE ENERGÍA',1.2)}
updateHUD()}
function updateHUD(){$('health').textContent='▰ '.repeat(Math.max(0,player.hp))+'▱ '.repeat(3-Math.max(0,player.hp));$('lives').textContent='× '+lives;$('score').textContent=String(score).padStart(6,'0');$('weapon').textContent=({rifle:'FUSIL / ∞',spread:'TRIPLE / '+player.ammo,beam:'BLÁSTER / '+player.ammo})[player.weapon];$('grenades').textContent='GRANADAS × '+player.grenades;$('progress').style.width=(player.x/world.width*100)+'%';$('boss-health').style.width=(world.boss.hp/world.boss.max*100)+'%'}
