for(const p of world.platforms){if(p.x>camera+1020||p.x+p.w<camera-30)continue;rect(p.x,p.y,p.w,p.h,'#293e3d');rect(p.x,p.y,p.w,4,d.accent);rect(p.x+6,p.y+5,p.w-12,5,'#769084');for(let x=p.x+12;x<p.x+p.w;x+=28)rect(x,p.y+12,12,6,'#122529');if(['factory','dam','space'].includes(d.type)){line([[p.x+10,p.y+15],[p.x+10,450]],d.ground,5);line([[p.x+p.w-10,p.y+15],[p.x+p.w-10,450]],d.ground,5)}}
