if(crouch){rect(-15,-12,22,9,'#263a35');rect(2,-7,17,7,'#102521')}else{poly([[-10,-20],[-1,-20],[stride+1,-5],[stride+5,0],[stride-6,0],[-10,-12]],'#263b35');poly([[0,-20],[9,-20],[7-stride,-4],[13-stride,0],[2-stride,0],[-3,-10]],'#3e5d4c');rect(stride-7,-3,13,4,'#132a27');rect(1-stride,-3,13,4,'#132a27')}
