function drawPlayer(){if(state==='dying'||(state==='over'&&lives<=0))return;if(player.inv>0&&Math.floor(clock*13)%2===0&&state!=='menu')return;const facing=player.face;const firing=keys.j&&state==='play';soldier(player.x,player.y,facing,'#80a26b',player.walk,player.crouch,firing&&!keys.w);if(keys.w&&state==='play'){const y=player.y-35;rect(player.x-3,y-23,6,25,'#92b5a0');rect(player.x-2,y-30,4,8,'#c1d7b6');if(firing)poly([[player.x-5,y-32],[player.x,y-45],[player.x+5,y-32]],'#fff4b0')}}
